// ---------------------------------------------------------------- masking
const KNOWN_PREFIXES = ["sk_live_", "rk_live_", "sk_test_", "sk-proj-", "sk-ant-", "sk-", "sb_secret_", "AKIA", "ASIA", "AIza", "ghp_", "github_pat_", "eyJ"];

